commit 4e722e260edd3188cd1a3f757632227aae6cdb25
Author:     welpy-cw <h.w.forms@arcor.de>
AuthorDate: Mon Aug 17 20:34:56 2026 +0100
Commit:     brendan@thunderbird.net <brendan@thunderbird.net>
CommitDate: Thu Aug 20 10:31:11 2026 +0000

    Bug 450059 - Don't reuse detached virtual folders in the folder lookup service. r=edicharry

    When a virtual folder is deleted or renamed, its C++ object is removed
    from the folder tree and becomes parentless. The folder lookup service
    retains a weak cache entry for its URI. If the object remains strongly
    referenced elsewhere, that weak reference continues to resolve to the
    detached object. When a new folder is later created at the same URI, the
    folder lookup service can therefore reuse the old object, causing the new
    folder to inherit its Virtual flag and saved-search state. A corresponding
    bandaid fix in nsMsgAccountManager::OnFolderRemoved clearing the flags on a
    virtual folder that is being deleted causes problems by accessing and (in
    the IMAP case) recreating the already deleted folder's database.

    Fix: in both CreateFolderAndCache (used by nsMsgDBFolder::AddSubfolder)
    and GetOrCreateFolderForURL (used by nsImapMailFolder::AddSubfolder and
    AddSubfolderWithPath), check whether a cached folder is still in the
    tree (has a parent). If not, and the cached folder is a virtual folder,
    remove the stale cache entry and create a fresh folder object via
    CreateDangling. The check is factored into
    MaybeDiscardParentlessVirtualFolder, shared by both entry points, and is
    skipped when Panorama is enabled (where the folder cache is managed
    differently).

    Parentlessness alone does not currently identify a stale cache entry:
    legacy folder creation and recreation paths can temporarily use parentless
    non-virtual folder objects. Therefore, limit this check to virtual folders.
    The check uses GetFlag rather than GetFlags so that it does not touch the
    deleted folder's message database, which would recreate its summary file.
    For the same reason, nsMsgAccountManager::OnFolderRemoved now uses GetFlag
    to test for the Virtual flag instead of GetFlags.

    Differential Revision: https://phabricator.services.mozilla.com/D314975

diff --git a/mailnews/base/src/FolderLookupService.cpp b/mailnews/base/src/FolderLookupService.cpp
index fa3e99ac248..f899389fc2d 100644
--- a/mailnews/base/src/FolderLookupService.cpp
+++ b/mailnews/base/src/FolderLookupService.cpp
@@ -11,6 +11,7 @@
 #include "mozilla/StaticPrefs_mail.h"
 #include "msgCore.h"
 #include "nsINetUtil.h"
+#include "nsMsgFolderFlags.h"
 #include "nsNetCID.h"

 /**
@@ -111,10 +112,15 @@ NS_IMETHODIMP FolderLookupService::CreateFolderAndCache(
   // equality by pointer for folders with the same URI, which is relied upon
   // throughout the codebase. This function is still an improvement over
   // `getOrCreateFromURL` because it enforces that folders all have a valid
-  // parent folder, so they can't dangle. This also has the side effect of
-  // maintaining any previously existing flags, but again, the code relies on
-  // that maintenance.
+  // parent folder, so they can't dangle.
   nsCOMPtr<nsIMsgFolder> folderToReturn = GetExisting(uri);
+
+  // If we found a cached folder, check whether it's still in the tree. A
+  // parentless virtual folder was previously deleted and must not be reused.
+  if (folderToReturn) {
+    MaybeDiscardParentlessVirtualFolder(uri, folderToReturn);
+  }
+
   if (!folderToReturn) {
     rv = CreateDangling(uri, getter_AddRefs(folderToReturn));
     NS_ENSURE_SUCCESS(rv, rv);
@@ -128,6 +134,8 @@ NS_IMETHODIMP FolderLookupService::CreateFolderAndCache(
   }

   // If the existing folder object has a parent, make sure it's the same parent.
+  // (At this point, folderToReturn either came from the cache with a parent,
+  // or was freshly created via CreateDangling with no parent yet.)
   nsCOMPtr<nsIMsgFolder> obtainedParent;
   rv = folderToReturn->GetParent(getter_AddRefs(obtainedParent));
   NS_ENSURE_SUCCESS(rv, rv);
@@ -170,6 +178,14 @@ NS_IMETHODIMP FolderLookupService::GetOrCreateFolderForURL(

   nsresult rv;
   nsCOMPtr<nsIMsgFolder> existingFolder = GetExisting(url);
+  if (existingFolder) {
+    // A cache entry can still resolve to a deleted or renamed folder if
+    // something else holds a strong reference to the folder object. Don't
+    // return a detached virtual folder: the caller would re-parent it and the
+    // new folder would incorrectly inherit the Virtual flag (and with it, the
+    // saved search's scope and terms).
+    MaybeDiscardParentlessVirtualFolder(url, existingFolder);
+  }
   if (existingFolder) {
     // The folder object exists and it has a server with a type,
     // indicating that the server hasn't been removed.
@@ -223,7 +239,7 @@ nsCOMPtr<nsIMsgFolder> FolderLookupService::GetExisting(const nsACString& url) {
   nsresult rv;
   nsCOMPtr<nsIMsgFolder> foundFolder{do_QueryReferent(*found, &rv)};
   if (NS_FAILED(rv)) {
-    // There are no more strong references to this folder, so we can delete it.
+    // The weak reference has expired, so remove its stale cache entry.
     mFolderCache.Remove(url);
     return nullptr;
   }
@@ -273,3 +289,24 @@ nsresult FolderLookupService::CreateDangling(const nsACString& url,

   return NS_OK;
 }
+
+void FolderLookupService::MaybeDiscardParentlessVirtualFolder(
+    const nsACString& url, nsCOMPtr<nsIMsgFolder>& folder) {
+  // This is a legacy folder-system concern; when Panorama is enabled the folder
+  // cache is managed differently, so never evict entries here.
+  if (mozilla::StaticPrefs::mail_panorama_enabled_AtStartup()) {
+    return;
+  }
+
+  nsCOMPtr<nsIMsgFolder> parent;
+  if (NS_FAILED(folder->GetParent(getter_AddRefs(parent))) || parent) {
+    return;
+  }
+
+  bool isVirtual = false;
+  folder->GetFlag(nsMsgFolderFlags::Virtual, &isVirtual);
+  if (isVirtual) {
+    mFolderCache.Remove(url);
+    folder = nullptr;
+  }
+}
diff --git a/mailnews/base/src/FolderLookupService.h b/mailnews/base/src/FolderLookupService.h
index 62d56b10a5f..1a06979e19c 100644
--- a/mailnews/base/src/FolderLookupService.h
+++ b/mailnews/base/src/FolderLookupService.h
@@ -34,6 +34,32 @@ class FolderLookupService final : public nsIFolderLookupService {
    * needs to be parented by a calling function.
    */
   nsresult CreateDangling(const nsACString& url, nsIMsgFolder** folder);
+  /**
+   * If the folder found in the cache for |url| is a parentless virtual folder,
+   * remove it from the cache and null out |folder| so that callers create a
+   * fresh folder object instead of reusing the stale one.
+   *
+   * The cache holds weak references. If a deleted or renamed virtual folder is
+   * still strongly referenced elsewhere, its cache entry continues to resolve
+   * to the detached folder object. Don't reuse that object: re-parenting it
+   * would cause those references to silently point to a completely different
+   * logical folder that incorrectly inherits the Virtual flag (and with it,
+   * the saved search's scope and terms).
+   *
+   * Parentlessness alone does not identify a stale cache entry: legacy folder
+   * creation and recreation paths can temporarily use parentless non-virtual
+   * folder objects. Therefore, this check cannot yet be generalized to all
+   * folders. `GetFlag` is used rather than `GetFlags` so that checking the flag
+   * doesn't touch the deleted folder's message database, which would recreate
+   * its summary file.
+   *
+   * This is a legacy folder-system concern; when Panorama is enabled the folder
+   * cache is managed differently and entries are never evicted here.
+   *
+   * On return, |folder| is null if the folder was discarded.
+   */
+  void MaybeDiscardParentlessVirtualFolder(const nsACString& url,
+                                           nsCOMPtr<nsIMsgFolder>& folder);

   nsTHashMap<nsCString, nsWeakPtr> mFolderCache;
 };
